/* Pip's Sky Islands: Helpers, icons, Pip the fox and shared drawings. Loaded in order by index.html; all files share one global scope. */
/* ================= helpers ================= */
const $=s=>document.querySelector(s);
let rand=Math.random;
const R=(a,b)=>Math.floor(rand()*(b-a+1))+a;
const pick=a=>a[Math.floor(rand()*a.length)];
const coin=()=>rand()<.5;
const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=R(0,i);[a[i],a[j]]=[a[j],a[i]]}return a};
const fmt=n=>n.toLocaleString('en-US');
const gcd=(a,b)=>b?gcd(b,a%b):a;
const frac=(a,b)=>`<span class="frac"><span>${a}</span><span>${b}</span></span>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const COLORS=['var(--coral)','var(--ocean)','var(--leaf)','var(--berry)'];
const FONT='font-family="Lilita One, Trebuchet MS, sans-serif"';
let DIFF=2;const Dv=(a,b,c)=>[a,b,c][DIFF-1];
function seeded(s){return function(){s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function numChoices(ans,arr){
  const out=[ans];
  for(const x of arr){if(out.length>=4)break;if(Number.isInteger(x)&&x>0&&!out.includes(x))out.push(x)}
  let g=0;while(out.length<4&&g++<80){const x=ans+R(-12,12);if(x>0&&!out.includes(x))out.push(x)}
  return {choices:shuffle(out.map(fmt)),answer:fmt(ans),numeric:true};
}
function strChoices(ans,arr,n=4){const out=[ans];for(const x of arr){if(out.length>=n)break;if(x&&!out.includes(x))out.push(x)}return {choices:shuffle(out),answer:ans}}
