function balloonDraw(b){
  let s='';
  if(b.rainbow)['#e2558f','#ff6b57','#ffc23d','#38b98a','#2f9fe0'].forEach((c,i)=>s+=`<ellipse cx="60" cy="46" rx="${44-i*9}" ry="44" fill="${c}"/>`);
  else s=`<ellipse cx="60" cy="46" rx="44" ry="44" fill="${b.c[0]}"/><ellipse cx="60" cy="46" rx="26" ry="44" fill="${b.c[1]}"/><ellipse cx="60" cy="46" rx="9" ry="44" fill="${b.c[0]}"/>`;
  if(b.seeds)s+=[[30,30],[34,52],[86,34],[90,56],[44,74],[76,72]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="1.3" ry="2.2" fill="#1f3557" opacity=".75"/>`).join('');
  if(b.facets)s+=`<path d="M16 46 L60 2 L104 46 L60 90Z M38 24 L82 68 M82 24 L38 68" stroke="#fff" stroke-width="1" fill="none" opacity=".7"/>`;
  if(b.stars)s+=[[30,34],[48,12],[78,22],[90,50],[40,64],[72,72],[60,40],[24,52]].map(([x,y])=>`<circle${b.twk?' class="twk"':''} cx="${x}" cy="${y}" r="${b.starC?2.3:1.9}" fill="${b.starC||'#ffd56b'}"/>`).join('');
  return s+`<ellipse cx="42" cy="26" rx="7" ry="13" fill="#fff" opacity=".35"/><path d="M42 84 Q60 94 78 84 L74 92 Q60 100 46 92Z" fill="${b.skirt}"/>`;
}
