function pieSVG(cx,cy,r,num,den,on='var(--berry)',off='#ffe4ee'){
  let s='';
  for(let i=0;i<den;i++){const a0=i/den*2*Math.PI-Math.PI/2,a1=(i+1)/den*2*Math.PI-Math.PI/2;
    const x0=cx+r*Math.cos(a0),y0=cy+r*Math.sin(a0),x1=cx+r*Math.cos(a1),y1=cy+r*Math.sin(a1);
    const fill=Array.isArray(on)?(on[i]||off):(i<num?on:off),cls=Array.isArray(on)&&on[i]?` class="fadein" style="animation-delay:${(on.delays||[])[i]||0}s;fill:${fill}"`:` style="fill:${fill}"`;
    s+=`<path d="M${cx} ${cy} L${x0.toFixed(2)} ${y0.toFixed(2)} A${r} ${r} 0 ${(a1-a0)>Math.PI?1:0} 1 ${x1.toFixed(2)} ${y1.toFixed(2)}Z"${cls} stroke="#fff" stroke-width="3" stroke-linejoin="round"/>`}
  return s+`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#1f3557" stroke-width="3"/>`;
}
