/* explanation animations */
function multAnim(side,parts,factor){
  const tot=parts.reduce((a,b)=>a+b,0),W=290,H=58;let x=40,s='',delay=0;
  parts.forEach((p,i)=>{const w=Math.max(46,W*p/tot*.9);s+=`<g><rect class="grow" style="animation-delay:${delay}s" x="${x}" y="32" width="${w-4}" height="${H}" rx="6" fill="${['#ffd56b','#8fd3f7','#9be0bd','#ffb3c7'][i%4]}" stroke="#1f3557" stroke-width="2"/>
    <text class="fadein" style="animation-delay:${delay}s" x="${x+(w-4)/2}" y="24" text-anchor="middle" ${FONT} font-size="16" fill="#1f3557">${fmt(p)}</text>
    <text class="fadein" style="animation-delay:${delay+.4}s" x="${x+(w-4)/2}" y="67" text-anchor="middle" ${FONT} font-size="15" fill="#1f3557">${fmt(p*factor)}</text></g>`;x+=w;delay+=.7});
  s+=`<text x="22" y="66" text-anchor="middle" ${FONT} font-size="18" fill="#ff6b57">${factor}</text><text class="fadein" style="animation-delay:${delay}s" x="${(40+x)/2}" y="120" text-anchor="middle" ${FONT} font-size="22" fill="#1f3557">${parts.map(p=>fmt(p*factor)).join(' + ')} = ${fmt(tot*factor)}</text>`;
  return `<svg viewBox="0 0 ${Math.max(340,x+20)} 132" style="width:${Math.max(340,x+20)}px" role="img" aria-label="Area model">${s}</svg>`;
}
